//! Differential ratchet for `src/engine/battleScriptBattlerPositions.ts`.
//! Expected outputs are generated by executing the canonical TypeScript
//! resolver; regenerate with `node --experimental-strip-types
//! core-rs/tools/gen-battle-script-battler-positions-vectors.mjs`.

use factory_core::battle_script_battler_positions::{
    resolve_single_battle_position, BattleScriptBattlerId, BattleScriptBattlersCount,
    BATTLE_SCRIPT_BATTLERS_COUNT_DOMAIN,
};
use factory_core::battle_script_battler_positions_vectors_gen::{
    BATTLE_SCRIPT_BATTLER_POSITION_BATTLERS_COUNT_DOMAIN,
    BATTLE_SCRIPT_BATTLER_POSITION_BRANCH_CENSUS, BATTLE_SCRIPT_BATTLER_POSITION_CASES,
    BATTLE_SCRIPT_BATTLER_POSITION_CATEGORY_CENSUS, BATTLE_SCRIPT_BATTLER_POSITION_DOMAIN_CENSUS,
    BATTLE_SCRIPT_BATTLER_POSITION_EXPRESSION_DOMAIN, BATTLE_SCRIPT_BATTLER_POSITION_RESULT_CENSUS,
    BATTLE_SCRIPT_BATTLER_POSITION_VECTOR_CORPUS_SHA256,
};

#[test]
fn complete_outputs_match_canonically_executed_typescript() {
    for (index, case) in BATTLE_SCRIPT_BATTLER_POSITION_CASES.iter().enumerate() {
        let actual = resolve_single_battle_position(case.battlers_count, case.expression)
            .map(BattleScriptBattlerId::as_u8);
        assert_eq!(
            actual, case.expected_battler,
            "case {index} {}: complete resolver output",
            case.label,
        );
    }
}

#[test]
fn typed_domain_preserves_count_gate_and_raw_attacker_collision() {
    assert_eq!(
        BATTLE_SCRIPT_BATTLERS_COUNT_DOMAIN.map(BattleScriptBattlersCount::as_u8),
        BATTLE_SCRIPT_BATTLER_POSITION_BATTLERS_COUNT_DOMAIN,
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_BATTLERS_COUNT_DOMAIN,
        [2, 4],
        "the native input type must retain all and only TypeScript's reachable counts",
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_EXPRESSION_DOMAIN,
        [
            "B_POSITION_PLAYER_LEFT",
            "B_POSITION_OPPONENT_LEFT",
            "BS_ATTACKER",
            "B_POSITION_PLAYER_RIGHT",
            "B_POSITION_OPPONENT_RIGHT",
            "BS_TARGET",
            "BS_PLAYER1",
            "",
            "1",
            "BS_ATTACKER ",
        ],
    );

    for battlers_count in BATTLE_SCRIPT_BATTLERS_COUNT_DOMAIN {
        assert_eq!(
            resolve_single_battle_position(battlers_count, "B_POSITION_PLAYER_LEFT"),
            Some(BattleScriptBattlerId::PlayerLeft),
        );
        assert_eq!(
            resolve_single_battle_position(battlers_count, "B_POSITION_OPPONENT_LEFT"),
            Some(BattleScriptBattlerId::OpponentLeft),
        );
        assert_eq!(
            resolve_single_battle_position(battlers_count, "BS_ATTACKER"),
            Some(BattleScriptBattlerId::OpponentLeft),
            "the raw byte spelling must not consult an attacker role",
        );
        assert!(BattleScriptBattlerId::PlayerLeft.as_u8() < battlers_count.as_u8());
        assert!(BattleScriptBattlerId::OpponentLeft.as_u8() < battlers_count.as_u8());
    }
}

#[test]
fn domain_category_branch_result_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_BATTLER_POSITION_CASES.len(), 20);
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_DOMAIN_CENSUS,
        [
            ("typed-battlers-count-values", 2),
            ("known-position-expressions", 3),
            ("unknown-expression-samples", 7),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_RESULT_CENSUS,
        [("0", 2), ("1", 4), ("null", 14)],
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_CATEGORY_CENSUS,
        [
            ("canonical-opponent-left", 2),
            ("canonical-player-left", 2),
            ("raw-bs-attacker-collision", 2),
            ("unknown-position", 4),
            ("unknown-raw-string", 6),
            ("unknown-selector", 4),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_BRANCH_CENSUS,
        [
            (
                "resolve-attacker-byte-as-opponent-left-through-count-gate",
                2
            ),
            ("resolve-opponent-left-through-count-gate", 2),
            ("resolve-player-left-through-count-gate", 2),
            ("unknown-expression-return-null", 14),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_BATTLER_POSITION_VECTOR_CORPUS_SHA256,
        "2539d9c708156a52587e8413abde4b379fa3839923b251212104307ab45d45eb",
    );
}
